def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        for y in range(y0 + 1, y1):
            for x in range(x0 + 1, x1, 2):
                if g[y, x] == o["colour"]:
                    g[y, x] = bg
        emit(g, f"Cut alternating gaps into the middle row(s) of the colour {o['colour']} rectangle at odd offsets from its left edge.")
    emit(g, "All rectangles now have comb-patterned middle rows.")
    return g
